using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task ClassInit(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            storageRootPath: Path.Combine(
                Directory.GetCurrentDirectory(), "evaluation-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator()
            ]);
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Greeting_ReturnsCoherentResponse()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Greeting_ReturnsCoherentResponse));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertNoFailures();
    }

    [TestMethod]
    public async Task FactualQuestion_ReturnsAccurateResponse()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(FactualQuestion_ReturnsAccurateResponse));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertNoFailures();
    }

    [TestMethod]
    public async Task MultiTurn_MaintainsContext()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(MultiTurn_MaintainsContext));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var response2 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertNoFailures();
    }
}

